// Файл создан скриптом tools/make_icons.py — не править вручную.

/// Номера значков; порядок совпадает с `GLYPHS`.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Icon {
    Dot,
    OilField,
    GasField,
    Drop,
    Flame,
    Refinery,
    Plant,
    Tank,
    Thermal,
    Coal,
    Hydro,
    Nuclear,
    Port,
    Airport,
    Pick,
    CoalMine,
    CoalTerminal,
    Solar,
    Wind,
    IronMine,
    GoldMine,
    CopperMine,
    ChemN,
    ChemPet,
    SteelBf,
    SteelEaf,
    Cement,
}

pub const ALL: [Icon; 27] = [
    Icon::Dot,
    Icon::OilField,
    Icon::GasField,
    Icon::Drop,
    Icon::Flame,
    Icon::Refinery,
    Icon::Plant,
    Icon::Tank,
    Icon::Thermal,
    Icon::Coal,
    Icon::Hydro,
    Icon::Nuclear,
    Icon::Port,
    Icon::Airport,
    Icon::Pick,
    Icon::CoalMine,
    Icon::CoalTerminal,
    Icon::Solar,
    Icon::Wind,
    Icon::IronMine,
    Icon::GoldMine,
    Icon::CopperMine,
    Icon::ChemN,
    Icon::ChemPet,
    Icon::SteelBf,
    Icon::SteelEaf,
    Icon::Cement,
];

impl Icon {
    pub fn key(self) -> &'static str {
        match self {
            Icon::Dot => "dot",
            Icon::OilField => "oil",
            Icon::GasField => "gas",
            Icon::Drop => "drop",
            Icon::Flame => "flame",
            Icon::Refinery => "factory",
            Icon::Plant => "plant",
            Icon::Tank => "tank",
            Icon::Thermal => "bolt",
            Icon::Coal => "coal",
            Icon::Hydro => "wave",
            Icon::Nuclear => "atom",
            Icon::Port => "port",
            Icon::Airport => "plane",
            Icon::Pick => "pick",
            Icon::CoalMine => "coalmine",
            Icon::CoalTerminal => "coalport",
            Icon::Solar => "solar",
            Icon::Wind => "wind",
            Icon::IronMine => "ironmine",
            Icon::GoldMine => "goldmine",
            Icon::CopperMine => "coppermine",
            Icon::ChemN => "chemn",
            Icon::ChemPet => "chempet",
            Icon::SteelBf => "steelbf",
            Icon::SteelEaf => "steeleaf",
            Icon::Cement => "cement",
        }
    }

    #[allow(dead_code)]
    pub fn title(self) -> &'static str {
        match self {
            Icon::Dot => "Точка",
            Icon::OilField => "Нефтедобыча",
            Icon::GasField => "Газодобыча",
            Icon::Drop => "Капля",
            Icon::Flame => "Огонь",
            Icon::Refinery => "НПЗ",
            Icon::Plant => "Завод",
            Icon::Tank => "Терминал / хранилище",
            Icon::Thermal => "Электростанция",
            Icon::Coal => "Уголь",
            Icon::Hydro => "Вода",
            Icon::Nuclear => "Атом",
            Icon::Port => "Порт",
            Icon::Airport => "Аэропорт",
            Icon::Pick => "Добыча",
            Icon::CoalMine => "Угольная шахта",
            Icon::CoalTerminal => "Угольный терминал",
            Icon::Solar => "Солнце",
            Icon::Wind => "Ветер",
            Icon::IronMine => "Железная руда",
            Icon::GoldMine => "Золотой рудник",
            Icon::CopperMine => "Медный рудник",
            Icon::ChemN => "Аммиак и метанол",
            Icon::ChemPet => "Нефтехимия",
            Icon::SteelBf => "Металлургический комбинат",
            Icon::SteelEaf => "Электросталь",
            Icon::Cement => "Цементный завод",
        }
    }

    pub fn from_key(key: &str) -> Option<Icon> {
        ALL.iter().copied().find(|i| i.key() == key)
    }

    /// Треугольники значка в единичном квадрате (по три точки, y вниз).
    pub fn tris(self) -> &'static [[f32; 2]] {
        GLYPHS[self as usize]
    }
}

